import{_ as a,C as i,c as l,o as h,a3 as o,G as s,j as n,a as r}from"./chunks/framework.Dokpd4od.js";const q=JSON.parse('{"title":"Create a quotation","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/create-quotation.md","filePath":"master/sales/sales/quotations-orders/create-quotation.md","lastUpdated":1793074831000}'),g={name:"master/sales/sales/quotations-orders/create-quotation.md"};function u(m,t,c,d,p,f){const e=i("ImagePopup");return h(),l("div",null,[t[0]||(t[0]=o('<h1 id="create-a-quotation" tabindex="-1">Create a quotation <a class="header-anchor" href="#create-a-quotation" aria-label="Permalink to &quot;Create a quotation&quot;">​</a></h1><p>A quotation is the offer you send to a customer before they buy. It lists what you sell, how many, at what price, with which taxes, and how long the offer stays open. You create one every time a customer asks &quot;how much would this cost?&quot;. When the customer says yes, the same record becomes a sales order, so you never type the data twice.</p><blockquote><p><strong>In simple words:</strong> A quotation is a draft order. You can change it freely until the customer agrees.</p></blockquote><p>Create the customer and the products first. See <a href="./manage-customers.html">Manage customers</a> and <a href="./../products-prices/manage-products.html">Manage products</a>. Customer and product names in this guide are sample names.</p><p>Throughout this page we use one example. Your customer <strong>Azure Interiors</strong> asks for 5 Camping Hammocks. You will build the quotation for them step by step.</p><h2 id="settings-that-change-this-page" tabindex="-1">Settings that change this page <a class="header-anchor" href="#settings-that-change-this-page" aria-label="Permalink to &quot;Settings that change this page&quot;">​</a></h2><p>Some fields appear only when you turn on a setting. If you cannot see a field mentioned here, check <code>Sales → Settings</code> first. See <a href="./../configuration/settings.html">Settings</a> for the full list.</p><ul><li><strong><em>Default Quotation Validity:</em></strong> Sets how many days a new quotation stays valid. It fills the <strong>Expiration</strong> date for you.</li><li><strong><em>Lock Confirm Sales:</em></strong> Locks an order after you confirm it, so nobody changes it by mistake.</li><li><strong><em>Discount:</em></strong> Adds a <strong>Discount (%)</strong> column to the order lines.</li><li><strong><em>Margins:</em></strong> Adds margin columns and a <strong>Margin</strong> total, so you can see your profit.</li><li><strong><em>Unit of Measure:</em></strong> Adds the <strong>UOM</strong> column.</li><li><strong><em>Packagings:</em></strong> Adds the <strong>Packaging Quantity</strong> and <strong>Packaging</strong> columns.</li><li><strong><em>Price Lists:</em></strong> Adds the <strong>Price List</strong> field in the General section.</li><li><strong><em>Variants:</em></strong> Lets you pick a product by its variant, such as size or colour.</li></ul><h2 id="the-quotation-list" tabindex="-1">The quotation list <a class="header-anchor" href="#the-quotation-list" aria-label="Permalink to &quot;The quotation list&quot;">​</a></h2><p>Go to <code>Sales → Orders → Quotations</code>. This page lists every quotation and order. Use it to find a record, check its status, or start a new quotation.</p>',10)),s(e,{src:"/images1/sales/quotation_list.png",alt:"Quotations list with view tabs, Group by, search box and the Total Amount summary row"}),t[1]||(t[1]=o('<h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the list are ready-made views:</p><ul><li><strong><em>Default:</em></strong> All quotations and orders.</li><li><strong><em>My Quotations:</em></strong> Only records where you are the sales person.</li><li><strong><em>Quotations:</em></strong> Records that are still quotations and not yet confirmed.</li><li><strong><em>Sales Orders:</em></strong> Confirmed orders.</li><li><strong><em>Archived:</em></strong> Deleted records. You can restore them from here.</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Number</strong>, <strong>Creation Date</strong>, <strong>Customer</strong>, <strong>Sales Person</strong>, <strong>Amount Total</strong> and <strong>Status</strong>. Number is the reference, such as SO/1.</p><p>Some columns are hidden at first. Open the column toggle icon to show them: <strong>Untaxed Amount</strong>, <strong>Amount Tax</strong>, <strong>Expected Date</strong>, <strong>Sales Team</strong>, <strong>Delivery Status</strong>, <strong>Invoice Status</strong> and <strong>Customer Reference</strong>.</p><p>At the bottom, a summary row adds up the <strong>Total Amount</strong> of the records you see. Use it to check, for example, how much value is waiting in open quotations.</p><h3 id="search-filter-and-group" tabindex="-1">Search, filter and group <a class="header-anchor" href="#search-filter-and-group" aria-label="Permalink to &quot;Search, filter and group&quot;">​</a></h3><ul><li><strong><em>Group by:</em></strong> Folds the list into groups. Choose from <strong>Medium</strong>, <strong>Source</strong>, <strong>Team</strong>, <strong>Sales Person</strong>, <strong>Currency</strong>, <strong>Company</strong>, <strong>Customer</strong>, <strong>Quotation Date</strong> or <strong>Commitment Date</strong>.</li><li><strong>Filters:</strong> Click the filter icon, then <strong>Add rule</strong>. Each rule picks a field, a condition and a value. Fields include <strong>Sales Person</strong>, <strong>UTM Source</strong>, <strong>Company</strong>, <strong>Customer</strong>, <strong>Payment Term</strong>, <strong>Currency</strong>, <strong>Created At</strong> and <strong>Updated At</strong>. Click <strong>Apply filters</strong> to see the result.</li></ul><p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a> for the general method.</p><h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><ul><li>Click the clock icon on a row to schedule an activity, such as &quot;call the customer on Friday&quot;. See <a href="./../../../getting-started/activities.html">Activities</a>.</li><li>Use the row menu to <strong>View</strong>, <strong>Edit</strong> or <strong>Delete</strong> a record. Confirmed orders cannot be deleted.</li><li>Tick several rows to delete them together. In the <strong>Archived</strong> view, tick rows to restore them.</li></ul><h2 id="create-a-quotation-1" tabindex="-1">Create a quotation <a class="header-anchor" href="#create-a-quotation-1" aria-label="Permalink to &quot;Create a quotation&quot;">​</a></h2><ol><li>Go to <code>Sales → Orders → Quotations</code>.</li><li>Click <strong>New Quotation</strong>.</li></ol>',14)),s(e,{src:"/images1/sales/quotation_list.png",alt:"Quotations list with the New Quotation button at the top right"}),t[2]||(t[2]=o('<p>The state bar at the top shows <strong>Quotation</strong>, <strong>Quotation Sent</strong> and <strong>Sales Order</strong>. It tells you where the record is in its life. A new record starts as <strong>Quotation</strong>. You cannot click the bar. It moves by itself when you send or confirm.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><p>This section holds the basics. Fill it first.</p><ul><li><strong><em>Customer:</em></strong> The person or company you are quoting. Required. Pick one from the list, or click the plus icon to create a new customer without leaving the page. Picking a customer also fills in the <strong>Sales Person</strong>, <strong>Payment Term</strong> and <strong>Price List</strong> saved on their contact.</li><li><strong><em>Expiration:</em></strong> The last day the offer is valid. Required. It is filled from <strong>Default Quotation Validity</strong> in the settings. For example, with 30 days you get a date one month away. Change it for a customer who needs more time. Once the quotation is saved, you see this date on the view page.</li><li><strong><em>Quotation Date:</em></strong> The date you make the offer. Required. It starts as today. After you confirm, the label changes to <strong>Order Date</strong>.</li><li><strong><em>Payment Term:</em></strong> The rule for when the customer must pay the invoice. Required. For example, <strong>Immediate Payment</strong> means the invoice is due at once. Another term might give 30 days. This is only a rule for the invoice. No money is taken on the quotation.</li><li><strong><em>Price List:</em></strong> A set of prices for a group of customers, for example wholesale. It shows only when <strong>Price Lists</strong> is on. If you choose one, the unit price of each line follows it. The price list can also set the currency.</li></ul><p><strong>Example:</strong> Choose <strong>Azure Interiors</strong>. Keep today as the <strong>Quotation Date</strong>. Keep <strong>Immediate Payment</strong> and the default <strong>Expiration</strong>.</p><h3 id="order-line" tabindex="-1">Order Line <a class="header-anchor" href="#order-line" aria-label="Permalink to &quot;Order Line&quot;">​</a></h3><p>This tab lists what you sell. Each line is one product.</p><ol><li>Click <strong>Add Product</strong>.</li><li>Choose the <strong>Product</strong>. Aureus fills the rest of the line for you.</li><li>Change anything that is different for this customer.</li><li>Repeat for each product.</li></ol>',8)),s(e,{src:"/images1/sales/quotation_order_line.png",alt:"Create Quotation page, Order Line tab with one product line filled in and the totals below"}),t[3]||(t[3]=o('<p>The columns are:</p><ul><li><strong><em>Product:</em></strong> What you sell. Required. With <strong>Variants</strong> on, you pick the exact variant.</li><li><strong><em>Quantity:</em></strong> How many the customer wants. Required. It starts at 1.</li><li><strong><em>UOM:</em></strong> The unit of measure, meaning the unit you count in, such as Units or Dozens. Shows only when <strong>Unit of Measure</strong> is on.</li><li><strong><em>Packaging Quantity:</em></strong> How many packs. Shows only when <strong>Packagings</strong> is on.</li><li><strong><em>Packaging:</em></strong> The pack type, such as a box of 6. Aureus suggests the best fit for your quantity.</li><li><strong><em>Unit Price:</em></strong> The price of one unit. It comes from the product, or from the price list. You can type a different price for this line.</li><li><strong><em>Taxes:</em></strong> The sales taxes of the product. You can add or remove taxes on the line.</li><li><strong><em>Discount (%):</em></strong> A percentage taken off the line. Shows only when <strong>Discount</strong> is on.</li><li><strong><em>Amount:</em></strong> The line total. Aureus calculates it, so you cannot edit it.</li></ul><p>A <strong>Lead Time</strong> column also exists. It is hidden at first. Use the column toggle to show it.</p><p><strong>Example:</strong> Click <strong>Add Product</strong> and choose <strong>Camping Hammock</strong>. Set <strong>Quantity</strong> to 5. Unit Price shows $65.00 and Taxes shows 15 %. The Amount is $325.00.</p><p>Below the lines, Aureus shows the totals:</p><ul><li><strong><em>Untaxed Amount:</em></strong> The sum of the lines before tax.</li><li><strong><em>Amount Tax:</em></strong> The tax on all lines.</li><li><strong><em>Amount Total:</em></strong> What the customer pays.</li><li><strong><em>Margin:</em></strong> Your profit on the quotation. Shows only when <strong>Margins</strong> is on.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To remove a line, click its delete icon and confirm.</p></div><p>See <a href="./../products-prices/discounts-margins.html">Discounts and margins</a> and <a href="./../configuration/packagings.html">Packagings</a>.</p><h3 id="optional-products" tabindex="-1">Optional Products <a class="header-anchor" href="#optional-products" aria-label="Permalink to &quot;Optional Products&quot;">​</a></h3><p>Use this tab for extras you want to suggest, such as a carry bag with the hammock. They do not change the total. See <a href="./optional-products.html">Optional products</a>.</p><h3 id="other-information" tabindex="-1">Other Information <a class="header-anchor" href="#other-information" aria-label="Permalink to &quot;Other Information&quot;">​</a></h3><p>This tab holds details that are good to have but not required.</p><p><strong>Sales</strong></p><ul><li><strong><em>Sales Person:</em></strong> The user in charge of this sale. It is filled from the customer.</li><li><strong><em>Customer Reference:</em></strong> The number your customer uses on their side, such as their purchase request number.</li><li><strong><em>Tags:</em></strong> Labels that help you search later. See <a href="./../configuration/tags.html">Tags</a>.</li></ul><p><strong>Shipping</strong></p><ul><li><strong><em>Warehouse:</em></strong> The warehouse that ships the goods. It appears when the Inventory plugin is installed.</li><li><strong><em>Delivery Date:</em></strong> The date you promise to deliver.</li></ul><p><strong>Tracking</strong></p><ul><li><strong><em>Source Document:</em></strong> The document this quotation came from, for example a customer email number.</li><li><strong><em>Campaign:</em></strong> The marketing campaign behind the sale.</li><li><strong><em>Medium:</em></strong> The channel, such as email or social media.</li><li><strong><em>Source:</em></strong> Where the customer found you, such as a website or a trade show.</li></ul><p>These fields feed the <strong>Group by</strong> and filter options on the list, so fill them if you want sales reports by channel.</p><p><strong>Additional Information</strong></p><ul><li><strong><em>Company:</em></strong> The company that issues the quotation. It starts as your current company.</li><li><strong><em>Currency:</em></strong> The currency of the quotation. It starts from your company and can follow the price list.</li></ul>',21)),s(e,{src:"/images1/sales/quotation_other_info.png",alt:"Other Information tab with the Sales, Shipping, Tracking and Additional Information sections"}),t[4]||(t[4]=n("h3",{id:"terms-conditions",tabindex:"-1"},[r("Terms & Conditions "),n("a",{class:"header-anchor",href:"#terms-conditions","aria-label":'Permalink to "Terms & Conditions"'},"​")],-1)),t[5]||(t[5]=n("p",null,[r("Write the "),n("strong",null,"Note"),r(" the customer should read, such as delivery terms or the validity of the price. Use the text editor to make it clear.")],-1)),s(e,{src:"/images1/sales/quotation_terms.png",alt:"Terms & Conditions tab with a note for the customer"}),t[6]||(t[6]=o('<h3 id="save-the-quotation" tabindex="-1">Save the quotation <a class="header-anchor" href="#save-the-quotation" aria-label="Permalink to &quot;Save the quotation&quot;">​</a></h3><ul><li>Click <strong>Create</strong> to save and open the quotation.</li><li>Click <strong>Create &amp; create another</strong> to save and start a blank one.</li><li>Click <strong>Cancel</strong> to leave without saving.</li></ul><h2 id="edit-a-quotation" tabindex="-1">Edit a quotation <a class="header-anchor" href="#edit-a-quotation" aria-label="Permalink to &quot;Edit a quotation&quot;">​</a></h2><p>Open the quotation and click the <strong>Edit</strong> tab. Change the fields, then click <strong>Save changes</strong>. You can edit a quotation until it is confirmed. After confirmation, the customer and the dates are locked. With <strong>Lock Confirm Sales</strong> on, the lines are locked too.</p><h2 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h2><p>A quotation does not take payment. Payment comes later, on the invoice. The steps are:</p><ol><li><strong>Payment Term:</strong> You choose it on the quotation. It sets the due date of the invoice. Terms are created in the Invoices app. See <a href="./../../../finance/customer-invoices/payment-terms.html">Payment terms</a>.</li><li><strong>Invoice:</strong> After you confirm the order, you create the invoice from it. See <a href="./../../../finance/customer-invoices/create-invoice.html">Create an invoice</a>.</li><li><strong>Register payment:</strong> When the customer pays, you record the payment on the invoice. See <a href="./../../../finance/payments/register-payment.html">Register a payment</a>.</li></ol><p>To follow the money on an order, open it and click the <strong>Invoices</strong> tab. It shows each invoice with its <strong>Payment State</strong> and <strong>Amount Due</strong>. See <a href="./manage-orders.html">Manage orders</a>.</p><p><strong>Example:</strong> Azure Interiors pays with <strong>Immediate Payment</strong>. Their invoice is due on the invoice date. When they pay, you register the payment and <strong>Amount Due</strong> drops to zero.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>A saved quotation has the status <strong>Quotation</strong>. Click <strong>Send By Email</strong> to move it to <strong>Quotation Sent</strong>. Click <strong>Confirm</strong> to make it a <strong>Sales Order</strong>. A quotation can also be cancelled. See <a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Chatter</strong> on the quotation to write notes, log messages or plan an activity. See <a href="./../../../getting-started/chatter.html">Chatter</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Check the <strong>Expiration</strong> date before you send. An old date makes the offer look expired.</p></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><ol><li>Click <strong>New Quotation</strong>.</li><li>Choose <strong>Azure Interiors</strong> as the <strong>Customer</strong>.</li><li>Keep <strong>Immediate Payment</strong> as the <strong>Payment Term</strong>.</li><li>On <strong>Order Line</strong>, add 5 <strong>Camping Hammock</strong> at $65.00.</li><li>In <strong>Terms &amp; Conditions</strong>, write &quot;Delivery within 7 days&quot;.</li><li>Click <strong>Create</strong>.</li><li>Click <strong>Send By Email</strong>, then <strong>Confirm</strong> when they agree.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./optional-products.html">Optional products</a></li><li><a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a></li><li><a href="./manage-orders.html">Manage orders</a></li><li><a href="./manage-customers.html">Manage customers</a></li><li><a href="./../products-prices/">Product prices</a></li></ul>',17))])}const w=a(g,[["render",u]]);export{q as __pageData,w as default};
